// golden_test.go — T-48: the generated-golden differential for the
// goodrepos module — the deterministic helpers, the frontmatter
// subset, the note parser's display-name ladder, THE README WRITER's
// exact bytes, scan_vault's shape, status(), the publish result (the
// deterministic sha: frozen clock + frozen git dates), the dry-run
// door, describe()/to_dict(), the owner door (the 401 hint), the
// creation guard's exact errors + the POST body, and the safety
// doors (the FETCH_HEAD scrub, _redact, the one-time token URL).
//
// testdata/goodrepos.golden.json is generated by
// testdiff/goldens/dump_goodrepos.py from the unmodified reference
// (assadigit/GitCurator @ 98f4fc7, the pinned venv's CPython 3.12.15
// stdlib) — no per-run facts inside: every temp-vault path is folded
// to '<vault>/…', every staging path to '<staging>/…', the CLOCK is
// frozen (the README date, the commit stamp, status()'s generated
// date), the GIT DATES are frozen (the deterministic commit sha), and
// duration_ms is zeroed.
//
// THE LAW: goldens are never hand-edited; a divergence is either a Go
// bug (fix the port) or a reference behavior change (regenerate + say
// so in the commit).
package goodrepos

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"testing"
	"time"

	"github.com/assadigit/second-brain-project/internal/storage"
)

var grGolden map[string]any

func loadGRGolden(t *testing.T) map[string]any {
	t.Helper()
	if grGolden != nil {
		return grGolden
	}
	data, err := os.ReadFile("testdata/goodrepos.golden.json")
	if err != nil {
		t.Fatalf("golden file: %v", err)
	}
	var g map[string]any
	if err := json.Unmarshal(data, &g); err != nil {
		t.Fatalf("golden json: %v", err)
	}
	grGolden = g
	return g
}

func grSection(t *testing.T, name string) map[string]any {
	t.Helper()
	v, ok := loadGRGolden(t)[name].(map[string]any)
	if !ok {
		t.Fatalf("golden section %q missing or not an object", name)
	}
	return v
}

func grValue(t *testing.T, name string) any {
	t.Helper()
	v, ok := loadGRGolden(t)[name]
	if !ok {
		t.Fatalf("golden value %q missing", name)
	}
	return v
}

// cmpGRGolden compares through the canonical Python dumps (maps sort
// keys; slices keep order) so the comparison is byte-honest.
func cmpGRGolden(t *testing.T, what string, got, want any) {
	t.Helper()
	g := storage.PyDumps(normGR(got))
	w := storage.PyDumps(normGR(want))
	if g != w {
		t.Errorf("%s diverges from the reference golden:\n got: %s\nwant: %s",
			what, g, w)
	}
}

// normGR normalizes Go values and JSON-decoded golden values onto the
// same comparable shape (the vaultseal normVS twin).
func normGR(v any) any {
	switch t := v.(type) {
	case string:
		return t
	case int:
		return float64(t)
	case int64:
		return float64(t)
	case bool, float64, nil:
		return t
	case json.Number:
		f, _ := t.Float64()
		return f
	case *int:
		if t == nil {
			return nil
		}
		return float64(*t)
	case *storage.OrderedMap:
		if t == nil {
			return nil
		}
		out := map[string]any{}
		for _, k := range t.Keys() {
			val, _ := t.Get(k)
			out[k] = normGR(val)
		}
		return out
	case map[string]any:
		if t == nil { // a nil map is Python's None, not {}
			return nil
		}
		out := map[string]any{}
		for k, val := range t {
			out[k] = normGR(val)
		}
		return out
	case map[string]bool:
		if t == nil {
			return nil
		}
		out := map[string]any{}
		for k, val := range t {
			out[k] = val
		}
		return out
	case map[string]string:
		out := map[string]any{}
		for k, val := range t {
			out[k] = val
		}
		return out
	case map[string]int:
		out := map[string]any{}
		for k, val := range t {
			out[k] = float64(val)
		}
		return out
	case []any:
		out := make([]any, len(t))
		for i, val := range t {
			out[i] = normGR(val)
		}
		return out
	case []string:
		out := make([]any, len(t))
		for i, s := range t {
			out[i] = s
		}
		return out
	case []int:
		out := make([]any, len(t))
		for i, n := range t {
			out[i] = float64(n)
		}
		return out
	case *PublishResult:
		return normGR(t.ToMap())
	default:
		return fmt.Sprintf("%v", v)
	}
}

// freezeClock mirrors the generator's _FrozenDatetime (2026-01-01
// 12:34 UTC) and restores the real clock afterwards.
func freezeClock(t *testing.T) {
	t.Helper()
	old := clockNow
	clockNow = func() time.Time {
		return time.Date(2026, 1, 1, 12, 34, 0, 0, time.UTC)
	}
	t.Cleanup(func() { clockNow = old })
}

// freezeGitDates mirrors the generator's GIT_AUTHOR_DATE /
// GIT_COMMITTER_DATE (the deterministic commit shas).
func freezeGitDates(t *testing.T) {
	t.Helper()
	t.Setenv("GIT_AUTHOR_DATE", "2026-01-01T12:34:56+00:00")
	t.Setenv("GIT_COMMITTER_DATE", "2026-01-01T12:34:56+00:00")
}

// foldGR folds the Go run's per-run paths away (the generator's fold
// twin): vault → '<vault>', staging → '<staging>'.
func foldGR(obj any, vault, staging string) any {
	switch t := obj.(type) {
	case string:
		if vault != "" && strings.HasPrefix(t, vault) {
			return "<vault>" + t[len(vault):]
		}
		if staging != "" && strings.HasPrefix(t, staging) {
			return "<staging>" + t[len(staging):]
		}
		return t
	case *storage.OrderedMap:
		out := storage.NewOrderedMap()
		for _, k := range t.Keys() {
			v, _ := t.Get(k)
			out.Set(k, foldGR(v, vault, staging))
		}
		return out
	case map[string]any:
		out := map[string]any{}
		for k, v := range t {
			out[k] = foldGR(v, vault, staging)
		}
		return out
	case []any:
		out := make([]any, len(t))
		for i, v := range t {
			out[i] = foldGR(v, vault, staging)
		}
		return out
	case []string:
		out := make([]any, len(t))
		for i, v := range t {
			out[i] = foldGR(v, vault, staging)
		}
		return out
	default:
		return obj
	}
}

// buildGoldenVault mirrors the generator's build_vault: the fixed
// 9-note vault across 6 category dirs + the root extras and noise.
func buildGoldenVault(t *testing.T, tmp string) string {
	t.Helper()
	root := filepath.Join(tmp, "vault")
	if err := os.MkdirAll(root, 0o755); err != nil {
		t.Fatal(err)
	}
	write := func(rel, text string) {
		path := filepath.Join(root, filepath.FromSlash(rel))
		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(path, []byte(text), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	write("AI-Domain/Agents/aaa_Agents_x.md",
		simpleNote("aaa", &simpleNoteOpts{stars: 100, tldr: strPtr("First agent summary.")}))
	write("AI-Domain/Agents/bbb_Agents_y.md",
		simpleNote("bbb", &simpleNoteOpts{stars: 900, tldr: strPtr("Second agent summary.")}))
	write("AI-Domain/Agents/eee_Agents_t.md",
		simpleNote("eee", &simpleNoteOpts{stars: 900, tldr: strPtr("Tie breaker rides the name.")}))
	write("AI-Domain/Skills/skl_Skills_s.md",
		simpleNote("skl", &simpleNoteOpts{stars: 5000, tldr: strPtr(""),
			category: "Skills"}))
	write("AI-Domain/LLM-Tools/ltl_LLM-Tools_l.md",
		noteText("https://github.com/ltl/ltl", "ltl", "ltl", "LLM-Tools",
			"14k", "", "The malformed-scalar note.", "not-a-list, malformed]",
			"Fallback description sentence."))
	write("AI-Domain/direct_Agents_d.md",
		simpleNote("direct", &simpleNoteOpts{stars: 42, tldr: strPtr("Direct child of the top.")}))
	write("Tools/Automation/ccc_Automation_z.md",
		simpleNote("ccc", &simpleNoteOpts{stars: 42, tldr: strPtr("Automation summary."),
			category: "Automation", lang: "Go", tags: "solo"}))
	write("Uncategorized/xxx_Uncategorized_y.md",
		"---\nsource: \"https://github.com/xxx/xxx\"\naliases: []\n"+
			"tags: not-a-list, malformed]\ncategory: \"\"\nstars: \"14k\"\n"+
			"org: \"\"\nprimary_language: \"\"\nlanguages: []\n"+
			"credibility_score: 78/100\ndate_processed: 2026-09-16\n---\n\n"+
			"# xxx\n\n> **TL;DR:** Weird frontmatter.\n\n"+
			"**`xxx/xxx`** · ⭐ ? · 🔧 ?\n")
	write("Uncategorized/zzz_Uncategorized_w.md",
		"# zzz\n\n> **TL;DR:** No frontmatter at all.\n")
	write("_index.md", "# Index\n")
	write("links_manifest.json",
		`{"generated": "2026-09-16", "links": [{"url": "https://github.com/aaa/aaa", "status": "processed"}]}`)
	write("README.md", "# the vault's own README (must NOT win)\n")
	write(".obsidian/app.json", "{}")
	write("_inbox/stray.md", simpleNote("stray", nil))
	return root
}

// stagingTree mirrors the generator's _tree: sorted rel paths,
// .git excluded.
func stagingTree(t *testing.T, staging string) []string {
	t.Helper()
	var out []string
	err := filepath.Walk(staging, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {
			if info.Name() == ".git" {
				return filepath.SkipDir
			}
			return nil
		}
		rel, err := filepath.Rel(staging, path)
		if err != nil {
			return err
		}
		out = append(out, strings.ReplaceAll(rel, string(filepath.Separator), "/"))
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	sort.Strings(out)
	return out
}

