func TestGolden_Helpers(t *testing.T) {
	fs := grSection(t, "format_stars")
	cases := map[string]any{
		"zero": 0, "plain": 999, "comma": 1234, "comma2": 9999,
		"ten_k": 10000, "fourteen_k": 14023, "rounds_up": 42987,
		"decimal": 86750, "large": 140232,
	}
	for name, v := range cases {
		cmpGRGolden(t, "format_stars."+name, FormatStarsAny(v), fs[name])
	}
	cmpGRGolden(t, "format_stars.none", FormatStarsAny(nil), fs["none"])
	cmpGRGolden(t, "format_stars.string", FormatStarsAny("14k"), fs["string"])

	anchors := grSection(t, "github_anchor")
	for name, want := range anchors {
		var input string
		switch name {
		case "ai_domain":
			input = "🤖 AI Domain"
		case "automation":
			input = "⚙️ Automation"
		case "agents_count":
			input = "🧠 Agents (2)"
		case "uncategorized":
			input = "📦 Uncategorized"
		case "llm_tools":
			input = "🧰 LLM Tools (1)"
		case "web_frameworks":
			input = "🌐 Web Frameworks (3)"
		case "plain":
			input = "Simple Heading"
		case "empty":
			input = ""
		case "punct":
			input = "What?! Really..."
		}
		cmpGRGolden(t, "github_anchor."+name, GitHubAnchor(input), want)
	}

	dn := grSection(t, "display_name")
	for name, want := range dn {
		input := map[string]string{
			"ai": "AI-Domain", "web": "Web-Frameworks", "plain": "Tools", "empty": "",
		}[name]
		cmpGRGolden(t, "display_name."+name, DisplayName(input), want)
	}

	ef := grSection(t, "emoji_for")
	cmpGRGolden(t, "emoji_for.single", EmojiFor("AI-Domain"), ef["single"])
	cmpGRGolden(t, "emoji_for.fallback", EmojiFor("No-Such-Category"), ef["fallback"])
	cmpGRGolden(t, "emoji_for.deepest", EmojiFor("AI-Domain", "Agents", "Frameworks"), ef["deepest"])
	cmpGRGolden(t, "emoji_for.empty_components", EmojiFor("", ""), ef["empty_components"])

	in := grSection(t, "intro_name")
	cmpGRGolden(t, "intro_name.ai", introName("AI Domain"), in["ai"])
	cmpGRGolden(t, "intro_name.tools", introName("Tools"), in["tools"])
	cmpGRGolden(t, "intro_name.mixed", introName("The Web Frameworks"), in["mixed"])
	cmpGRGolden(t, "intro_name.long_caps", introName("HTTP Server Stuff"), in["long_caps"])
}

