func TestGolden_Frontmatter(t *testing.T) {
	fm := grSection(t, "parse_frontmatter")
	cases := map[string][]string{
		"scalar_quoted":      {"---", "source: \"https://github.com/a/b\"", "---"},
		"inline_list":        {"---", "tags: [alpha, beta]", "---"},
		"inline_list_spaces": {"---", "tags: [ alpha ,  beta ]", "---"},
		"empty_list":         {"---", "aliases: []", "---"},
		"block_list":         {"---", "aliases:", "  - one", "  - two/and", "---"},
		"block_after_scalar": {"---", "category: Agents", "tags:", "  - solo", "---"},
		"block_after_string": {"---", "category: Agents", "aliases:", "  - x", "---"},
		"no_close":           {"---", "category: Agents"},
		"no_frontmatter":     {"# just a body"},
		"stars_string":       {"---", "stars: \"14k\"", "---"},
		"stars_comma":        {"---", "stars: \"1,402\"", "---"},
		"malformed_tags":     {"---", "tags: not-a-list, malformed]", "---"},
		"quoted_strip":       {"---", "source: \"  padded  \"", "---"},
	}
	for name, lines := range cases {
		m := parseFrontmatter(lines)
		out := map[string]any{}
		for _, k := range m.keys {
			v, _ := m.get(k)
			out[k] = v
		}
		cmpGRGolden(t, "parse_frontmatter."+name, out, fm[name])
	}

	at := grValue(t, "as_tags").([]any)
	tagsInputs := []any{
		[]any{"cp", "python"}, "cp, python", "solo", "not-a-list, malformed]",
		"", nil, []any{}, "[a, b]", "quoted, \"things\"",
	}
	tagsKeys := []string{"0", "1", "2", "3", "4", "5", "6", "7", "8"}
	for i, v := range tagsInputs {
		cmpGRGolden(t, "as_tags."+tagsKeys[i], asTags(v), at[i])
	}

	aa := grValue(t, "as_aliases").([]any)
	aliasInputs := []any{
		[]any{"a", "a/b", "  "}, "solo", "", nil, []any{},
	}
	aliasKeys := []string{"0", "1", "2", "3", "4", "5"}
	for i, v := range aliasInputs {
		cmpGRGolden(t, "as_aliases."+aliasKeys[i], asAliases(v), aa[i])
	}

	ti := grValue(t, "to_int").([]any)
	intInputs := []any{42, "1234", "1,402", "14k", true, false, nil, "", "-7"}
	intKeys := []string{"0", "1", "2", "3", "4", "5", "6", "7", "8"}
	for i, v := range intInputs {
		cmpGRGolden(t, "to_int."+intKeys[i], toInt(v), ti[i])
	}

	ou := grValue(t, "owner_repo_from_url").([]any)
	urlInputs := []any{
		"https://github.com/owner/repo",
		"https://github.com/owner/repo.git",
		"https://github.com/owner/repo/issues/42",
		"https://gitlab.com/owner/repo", "", nil,
		"https://github.com/aaa/aaa.git/tree/main",
	}
	urlKeys := []string{"0", "1", "2", "3", "4", "5", "6"}
	for i, v := range urlInputs {
		cmpGRGolden(t, "owner_repo_from_url."+urlKeys[i], ownerRepoFromURL(v), ou[i])
	}
}

