func TestGolden_ParseNote(t *testing.T) {
	want := grSection(t, "parse_note")
	tmp := t.TempDir()
	root := filepath.Join(tmp, "vault")
	if err := os.MkdirAll(filepath.Join(root, "AI-Domain", "Agents"), 0o755); err != nil {
		t.Fatal(err)
	}
	write := func(name, text string) {
		if err := os.WriteFile(filepath.Join(root, "AI-Domain", "Agents", name),
			[]byte(text), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	write("aaa_Agents_x.md", strings.ReplaceAll(simpleNote("aaa", nil),
		"https://github.com/aaa/aaa", "https://github.com/aaa/aaa.git/tree/main"))
	write("bbb_Agents_y.md", strings.ReplaceAll(simpleNote("bbb", nil),
		`source: "https://github.com/bbb/bbb"`, `source: ""`))
	write("ccc_Agents_z.md", strings.ReplaceAll(
		noteText("", "ccc", "ccc", "Agents", 7, "Go", "C summary.", "t",
			"Fallback description sentence."),
		"  - ccc\n  - ccc/ccc", "  - ccc"))
	write("ddd_Agents_w.md", "# ddd\n\nno frontmatter at all, just a body\n")
	write("eee_Agents_v.md", simpleNote("eee", &simpleNoteOpts{tldr: strPtr("")}))
	write("fff_Agents_u.md", strings.ReplaceAll(simpleNote("fff", nil),
		"tags: [alpha, beta]", "tags: [solo, other]"))

	for _, name := range []string{
		"aaa_Agents_x", "bbb_Agents_y", "ccc_Agents_z",
		"ddd_Agents_w", "eee_Agents_v", "fff_Agents_u",
	} {
		n := ParseNote(filepath.Join(root, "AI-Domain", "Agents", name+".md"),
			"AI-Domain/Agents/"+name+".md")
		got := map[string]any{
			"rel_path":       n.RelPath,
			"display":        n.Display,
			"url":            n.URL,
			"title":          n.Title,
			"tldr":           n.Tldr,
			"tags":           n.Tags,
			"stars":          n.Stars,
			"language":       n.Language,
			"category":       n.Category,
			"date_processed": n.DateProcessed,
			"credibility":    n.Credibility,
		}
		cmpGRGolden(t, "parse_note."+name, got, want[name])
	}
}

// ---------------------------------------------------------------------------
// THE README (the fixed vault, frozen clock)
// ---------------------------------------------------------------------------

func TestGolden_Readme(t *testing.T) {
	freezeClock(t)
	want := grSection(t, "readme")

	vault := buildGoldenVault(t, t.TempDir())
	pub := NewGoodRepos(vault, "", "good-repos", false, true, 0, nil, false)
	t.Cleanup(func() { dropStaging(pub) })
	cats := pub.ScanVault()
	cmpGRGolden(t, "readme.main", pub.buildReadme(cats), want["main"])

	// the single-entry vault (the plural doors)
	tmp := t.TempDir()
	single := filepath.Join(tmp, "vault")
	if err := os.MkdirAll(filepath.Join(single, "AI-Domain", "Agents"), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(single, "AI-Domain", "Agents", "one_Agents_o.md"),
		[]byte(simpleNote("one", &simpleNoteOpts{stars: 3, tldr: strPtr("The only curated repo.")})),
		0o644); err != nil {
		t.Fatal(err)
	}
	pub2 := NewGoodRepos(single, "", "good-repos", false, true, 0, nil, false)
	t.Cleanup(func() { dropStaging(pub2) })
	cmpGRGolden(t, "readme.single", pub2.buildReadme(pub2.ScanVault()), want["single"])

	// the empty vault README (0 repos / 0 categories)
	pub3 := NewGoodRepos(single, "", "good-repos", false, true, 0, nil, false)
	t.Cleanup(func() { dropStaging(pub3) })
	cmpGRGolden(t, "readme.empty", pub3.buildReadme(nil), want["empty"])
}

// ---------------------------------------------------------------------------
// scan_vault + status()
// ---------------------------------------------------------------------------

func TestGolden_ScanAndStatus(t *testing.T) {
	freezeClock(t)
	scanW := grSection(t, "scan")
	statusW := grValue(t, "status")

	vault := buildGoldenVault(t, t.TempDir())
	pub := NewGoodRepos(vault, "", "good-repos", false, true, 0, nil, false)
	t.Cleanup(func() { dropStaging(pub) })
	cats := pub.ScanVault()

	catsMap := map[string]any{}
	entries := 0
	for _, c := range cats {
		var displays []string
		for _, n := range c.Notes {
			displays = append(displays, n.Display)
		}
		catsMap[c.Rel] = displays
		entries += len(c.Notes)
	}
	cmpGRGolden(t, "scan.cats", catsMap, scanW["cats"])
	cmpGRGolden(t, "scan.entries", entries, scanW["entries"])
	cmpGRGolden(t, "scan.categories", len(cats), scanW["categories"])

	cmpGRGolden(t, "status", foldGR(pub.Status(), vault, ""), statusW)
}

