func TestGolden_PublishResult(t *testing.T) {
	freezeClock(t)
	freezeGitDates(t)
	want := grSection(t, "publish_result")
	wantTwice := grValue(t, "publish_twice")

	vault := buildGoldenVault(t, t.TempDir())
	pub := NewGoodRepos(vault, "", "good-repos", false, true, 0, nil, false)
	t.Cleanup(func() { dropStaging(pub) })
	result := pub.Publish(nil, false)
	staging := pub.staging

	d := result.ToMap()
	d.Set("duration_ms", 0)
	cmpGRGolden(t, "publish_result.to_dict", foldGR(d, vault, staging), want["to_dict"])
	cmpGRGolden(t, "publish_result.staging_tree", stagingTree(t, staging), want["staging_tree"])

	cfgData, err := os.ReadFile(filepath.Join(staging, ".git", "config"))
	if err != nil {
		t.Fatal(err)
	}
	cmpGRGolden(t, "publish_result.git_config", string(cfgData), want["git_config"])

	// the second publish on the same instance skips
	second := pub.Publish(nil, false)
	d2 := second.ToMap()
	d2.Set("duration_ms", 0)
	cmpGRGolden(t, "publish_twice", foldGR(d2, vault, staging), wantTwice)
}

func TestGolden_DryRun(t *testing.T) {
	freezeClock(t)
	want := grSection(t, "dry_run")

	vault := buildGoldenVault(t, t.TempDir())
	pub := NewGoodRepos(vault, "", "good-repos", false, true, 0, nil, false)
	t.Cleanup(func() { dropStaging(pub) })
	result := pub.Publish(nil, true)
	staging := result.StagingDir
	t.Cleanup(func() { _ = os.RemoveAll(staging) })

	d := result.ToMap()
	d.Set("duration_ms", 0)
	cmpGRGolden(t, "dry_run.to_dict", foldGR(d, vault, staging), want["to_dict"])
	cmpGRGolden(t, "dry_run.staging_tree", stagingTree(t, staging), want["staging_tree"])
	cmpGRGolden(t, "dry_run.describe",
		strings.ReplaceAll(result.Describe(), staging, "<staging>"), want["describe"])
}

