func TestGolden_DescribeAndDict(t *testing.T) {
	want := grSection(t, "describe")
	td := grValue(t, "to_dict")

	r := &PublishResult{
		Published: true, Pushed: true, FilesChanged: 7,
		CommitSha: "abc1234", CommitMessage: "publish: x repos — y",
		RepoName: "o/r", RepoURL: "https://github.com/o/r",
		Entries: 3, Categories: 2, DurationMS: 12,
	}
	cmpGRGolden(t, "describe.full", r.Describe(), want["full"])
	cmpGRGolden(t, "describe.skipped",
		(&PublishResult{SkippedReason: "x"}).Describe(), want["skipped"])
	cmpGRGolden(t, "describe.failed",
		(&PublishResult{Error: "boom"}).Describe(), want["failed"])
	cmpGRGolden(t, "describe.failed_published",
		(&PublishResult{Error: "boom", Published: true}).Describe(), want["failed_published"])
	cmpGRGolden(t, "describe.dry_run",
		(&PublishResult{Published: true, DryRun: true, Entries: 3, Categories: 2,
			StagingDir: "/tmp/gr-x"}).Describe(), want["dry_run"])
	cmpGRGolden(t, "describe.no_push",
		(&PublishResult{Published: true, Entries: 3, Categories: 2}).Describe(), want["no_push"])

	tdMap := td.(map[string]any)
	cmpGRGolden(t, "to_dict.full", r, tdMap["full"])
	cmpGRGolden(t, "to_dict.empty", &PublishResult{}, tdMap["empty"])
	okLaws := tdMap["ok_laws"].(map[string]any)
	cmpGRGolden(t, "ok_laws.plain_ok", (&PublishResult{}).OK(), okLaws["plain_ok"])
	cmpGRGolden(t, "ok_laws.skipped_ok",
		(&PublishResult{SkippedReason: "x"}).OK(), okLaws["skipped_ok"])
	cmpGRGolden(t, "ok_laws.error_not_ok",
		(&PublishResult{Error: "e"}).OK(), okLaws["error_not_ok"])
	cmpGRGolden(t, "ok_laws.published_ok",
		(&PublishResult{Published: true}).OK(), okLaws["published_ok"])
}

// ---------------------------------------------------------------------------
// The owner door + the creation guard
// ---------------------------------------------------------------------------

func captureOwner(status int, payload map[string]any) (any, []any) {
	var logs []any
	s := NewGoodRepos("/v", "tok", "r", true, true, 0, func(msg, level string) {
		logs = append(logs, []any{level, msg})
	}, false)
	s.apiFn = func(method, path string, body map[string]any) (int, map[string]any) {
		return status, payload
	}
	login := s.ownerLogin()
	if login == "" { // the Python None door re-opens as null
		return nil, logs
	}
	return login, logs
}

func TestGolden_OwnerLogin(t *testing.T) {
	want := grSection(t, "owner_login")
	login, logs := captureOwner(200, map[string]any{"login": "testuser"})
	cmpGRGolden(t, "owner_login.good", []any{login, logs}, want["good"])
	cmpGRGolden(t, "owner_login.empty_login",
		ownerPair(captureOwner(200, map[string]any{"login": ""})), want["empty_login"])
	cmpGRGolden(t, "owner_login.unauthorized",
		ownerPair(captureOwner(401, map[string]any{"message": "Bad credentials"})), want["unauthorized"])
	cmpGRGolden(t, "owner_login.server_error",
		ownerPair(captureOwner(500, map[string]any{"message": "oops"})), want["server_error"])
	cmpGRGolden(t, "owner_login.network",
		ownerPair(captureOwner(0, map[string]any{"message": "timed out"})), want["network"])
}

// ownerPair boxes the (login, logs) pair for the golden comparison.
func ownerPair(login any, logs []any) []any { return []any{login, logs} }

func goldenGuard(repoName string, allowCreate bool,
	responses map[[2]string][2]any) map[string]any {
	var calls []any
	s := NewGoodRepos("/tmp/guard", "tok", repoName, true, true, 0, nil, allowCreate)
	s.apiFn = func(method, path string, body map[string]any) (int, map[string]any) {
		calls = append(calls, []any{method, path, body})
		if r, ok := responses[[2]string{method, path}]; ok {
			payload, _ := r[1].(map[string]any)
			if r[1] == nil {
				payload = map[string]any{}
			}
			status, _ := r[0].(int)
			return status, payload
		}
		return 404, map[string]any{"message": "Not Found"}
	}
	ok, err := s.ensureRepo()
	var errAny any // the Python None door re-opens as null
	if err != "" {
		errAny = err
	}
	return map[string]any{"ok": ok, "err": errAny, "calls": calls}
}

func TestGolden_CreationGuard(t *testing.T) {
	want := grSection(t, "creation_guard")
	cmpGRGolden(t, "creation_guard.no_opt_in", goldenGuard("curated-dir", false,
		map[[2]string][2]any{
			{"GET", "/user"}:                       {200, map[string]any{"login": "testuser"}},
			{"GET", "/repos/testuser/curated-dir"}: {404, map[string]any{"message": "Not Found"}},
		}), want["no_opt_in"])
	cmpGRGolden(t, "creation_guard.allow_create", goldenGuard("curated-dir", true,
		map[[2]string][2]any{
			{"GET", "/user"}:                       {200, map[string]any{"login": "testuser"}},
			{"GET", "/repos/testuser/curated-dir"}: {404, map[string]any{"message": "Not Found"}},
			{"POST", "/user/repos"}:                {201, map[string]any{"full_name": "testuser/curated-dir"}},
		}), want["allow_create"])
	cmpGRGolden(t, "creation_guard.empty_name", goldenGuard("", false,
		map[[2]string][2]any{}), want["empty_name"])
	cmpGRGolden(t, "creation_guard.existing", goldenGuard("curated-dir", false,
		map[[2]string][2]any{
			{"GET", "/user"}:                       {200, map[string]any{"login": "testuser"}},
			{"GET", "/repos/testuser/curated-dir"}: {200, map[string]any{"private": true}},
		}), want["existing"])
	cmpGRGolden(t, "creation_guard.api_error", goldenGuard("curated-dir", false,
		map[[2]string][2]any{
			{"GET", "/user"}:                       {200, map[string]any{"login": "testuser"}},
			{"GET", "/repos/testuser/curated-dir"}: {403, map[string]any{"message": "nope"}},
		}), want["api_error"])
	cmpGRGolden(t, "creation_guard.create_race_422", goldenGuard("curated-dir", true,
		map[[2]string][2]any{
			{"GET", "/user"}:                       {200, map[string]any{"login": "testuser"}},
			{"GET", "/repos/testuser/curated-dir"}: {404, map[string]any{"message": "Not Found"}},
			{"POST", "/user/repos"}:                {422, map[string]any{"message": "name already exists"}},
		}), want["create_race_422"])
}

// ---------------------------------------------------------------------------
// The safety doors
// ---------------------------------------------------------------------------

func TestGolden_SafetyDoors(t *testing.T) {
	want := loadGRGolden(t)

	// the FETCH_HEAD scrub
	tmp := t.TempDir()
	staging := filepath.Join(tmp, "staging")
	if err := os.MkdirAll(filepath.Join(staging, ".git"), 0o755); err != nil {
		t.Fatal(err)
	}
	fh := filepath.Join(staging, ".git", "FETCH_HEAD")
	if err := os.WriteFile(fh, []byte("abc123\t\tbranch 'main' of "+
		"https://x-access-token:SECRETTOKEN@github.com/o/r.git\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	s := NewGoodRepos("/v", "SECRETTOKEN", "r", true, true, 0, nil, false)
	s.staging = staging
	s.sanitizeFetchHead()
	data, _ := os.ReadFile(fh)
	cmpGRGolden(t, "fetch_head_scrub", string(data), want["fetch_head_scrub"])

	// no token → untouched
	if err := os.WriteFile(fh, []byte(
		"https://x-access-token:SECRETTOKEN@github.com/o/r.git\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	s2 := NewGoodRepos("/v", "", "r", false, true, 0, nil, false)
	s2.staging = staging
	s2.sanitizeFetchHead()
	data2, _ := os.ReadFile(fh)
	cmpGRGolden(t, "fetch_head_no_token", string(data2), want["fetch_head_no_token"])

	// _redact
	red := grSection(t, "redact")
	s3 := NewGoodRepos("/v", "SECRETTOKEN", "r", false, true, 0, nil, false)
	cmpGRGolden(t, "redact.hit",
		s3.redact("url https://x-access-token:SECRETTOKEN@github.com/o end"), red["hit"])
	cmpGRGolden(t, "redact.miss", s3.redact("nothing here"), red["miss"])
	cmpGRGolden(t, "redact.no_token",
		NewGoodRepos("/v", "", "r", false, true, 0, nil, false).
			redact("SECRETTOKEN stays"), red["no_token"])

	// the one-time token URL
	s4 := NewGoodRepos("/v", "TOK", "r", true, true, 0, nil, false)
	s4.repoFull = "owner/repo"
	cmpGRGolden(t, "token_url", s4.tokenURLFn(), want["token_url"])
}
